begin;
-- Simulate Storage API deletion only inside this rolled-back test transaction.
set local storage.allow_delete_query = 'true';
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.aid(label text) returns uuid language sql immutable as $$select md5('apparel:'||label)::uuid$$;
create temporary table apparel_state(k text primary key,v jsonb);
create function pg_temp.keep(k text,v jsonb) returns void language sql as $$insert into apparel_state values(k,v) on conflict(k) do update set v=excluded.v$$;
create function pg_temp.state(k text) returns jsonb language sql as $$select v from apparel_state where apparel_state.k=$1$$;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(pg_temp.aid('owner'),'apparel@test.local',now(),false),(pg_temp.aid('other'),'other-apparel@test.local',now(),false);
insert into public.sessions(id,user_id,title) values(pg_temp.aid('session'),pg_temp.aid('owner'),'Apparel');
insert into public.reference_uploads(id,user_id,session_id,storage_path,original_filename,mime_type,size_bytes,width,height)
 select pg_temp.aid('source-'||i),pg_temp.aid('owner'),pg_temp.aid('session'),'source/'||i,i||'.jpg',case when i=7 then 'image/png' else 'image/jpeg' end,100,600,800 from generate_series(1,7) i;
create function pg_temp.plan() returns jsonb language sql as $$select jsonb_build_object('engine','apparel-catalog','scene','apparel-catalog','layoutVersion','1.0.0','brief',jsonb_build_object('sku','A1','name','亚麻衬衫','color','白色','composition','100 亚麻','care','冷水手洗','size','M','measurements',jsonb_build_object('length','65','chest','100','shoulder','40','sleeve','58'),'weightRecommendation','45–55kg','design','自然舒适。','fabric','亚麻面料。'),'sources',jsonb_build_object('mains',(select jsonb_agg(pg_temp.aid('source-'||i)) from generate_series(1,5) i),'displays',jsonb_build_array(jsonb_build_object('id',pg_temp.aid('source-6'),'name','展示1.jpg')),'logo',pg_temp.aid('source-7')),'fabricCrop',jsonb_build_array(.24,.20,.76,.57))$$;
create function pg_temp.call(op text,body jsonb default '{}',owner uuid default pg_temp.aid('owner')) returns jsonb language sql as $$select public.apparel_dispatch(owner,op,case when op in ('create','list') then null else (pg_temp.state('task')->>'id')::uuid end,body,md5(op||body::text),gen_random_uuid())$$;
select ok(not has_function_privilege('authenticated','public.apparel_dispatch(uuid,text,uuid,jsonb,text,uuid)','execute'),'client cannot spoof catalog owner');
select pg_temp.keep('create',jsonb_build_object('requestId',pg_temp.aid('create'),'sessionId',pg_temp.aid('session'),'plan',pg_temp.plan()));
select pg_temp.keep('task',pg_temp.call('create',pg_temp.state('create')));
select is(pg_temp.call('create',pg_temp.state('create'))->>'id',pg_temp.state('task')->>'id','create request deduplicates');
select throws_ok($$select pg_temp.call('create',jsonb_set(pg_temp.state('create'),'{plan,brief,name}','"改变"'))$$,'P0001','idempotency_conflict','changed request rejected');
select throws_ok($$select pg_temp.call('get','{}',pg_temp.aid('other'))$$,'P0001','task_not_found','account isolation');
select is(jsonb_array_length(public.commerce_dispatch(pg_temp.aid('owner'),'list',null,jsonb_build_object('sessionId',pg_temp.aid('session')),null,null,gen_random_uuid())),0,'AI task list excludes catalog');
select is(jsonb_array_length(pg_temp.call('list',jsonb_build_object('sessionId',pg_temp.aid('session')))),1,'catalog history uses same session');
select pg_temp.keep('submit',jsonb_build_object('requestId',pg_temp.aid('submit'),'revision',1));
select pg_temp.keep('claim',pg_temp.call('submit',pg_temp.state('submit')));
select is(pg_temp.state('claim')->>'claimed','true','first execution claims a lease');
select is(pg_temp.call('submit',pg_temp.state('submit'))->>'claimed','false','duplicate does not render twice');
select throws_ok($$select pg_temp.call('submit',jsonb_set(pg_temp.state('submit'),'{requestId}',to_jsonb(pg_temp.aid('competing'))))$$,'P0001','apparel_account_busy','one active set per account');
select pg_temp.keep('fence',jsonb_build_object('runId',pg_temp.state('claim')->'runId','claimToken',pg_temp.state('claim')->'claimToken'));
select is(jsonb_array_length(pg_temp.call('sources',pg_temp.state('fence'))),7,'frozen revision sources owned and active');
select pg_temp.keep('intent',pg_temp.call('register',pg_temp.state('fence')||jsonb_build_object('name','主图/1.jpg','width',750,'height',1000)));
select is((select uploaded from public.apparel_assets where id=(pg_temp.state('intent')->>'id')::uuid),false,'Storage intent persists before upload');
select throws_ok($$select pg_temp.call('complete',pg_temp.state('fence'))$$,'P0001','apparel_incomplete','partial set cannot complete');
select pg_temp.call('fail',pg_temp.state('fence')||'{"error":"retry"}');
select pg_temp.keep('retry',pg_temp.call('submit',pg_temp.state('submit')));
select is(pg_temp.state('retry')->>'runId',pg_temp.state('claim')->>'runId','failed request resumes same execution identity');
select ok(pg_temp.state('retry')->>'claimToken'<>pg_temp.state('claim')->>'claimToken','retry fences old process');
select throws_ok($$select pg_temp.call('renew',pg_temp.state('fence'))$$,'P0001','apparel_lease_lost','old process cannot publish');
select pg_temp.keep('fence',jsonb_build_object('runId',pg_temp.state('retry')->'runId','claimToken',pg_temp.state('retry')->'claimToken'));
do $$declare name text; intent jsonb;begin for name in select '主图/'||i||'.jpg' from generate_series(1,5) i union all select 'images/详情2_'||lpad(i::text,2,'0')||'.jpg' from unnest(array[1,3,4,5,6,7]) i loop intent:=pg_temp.call('register',pg_temp.state('fence')||jsonb_build_object('name',name,'width',case when name like '主图%' then 750 else 790 end,'height',1000));perform pg_temp.call('uploaded',pg_temp.state('fence')||jsonb_build_object('assetId',intent->'id'));end loop;end$$;
select pg_temp.keep('complete',pg_temp.call('complete',pg_temp.state('fence')));
select is(jsonb_array_length(pg_temp.state('complete')#>'{runs,0,assets}'),11,'one set has 11 assets');
select is(pg_temp.call('submit',pg_temp.state('submit'))->>'claimed','false','success replay does not execute');
select is((select count(*) from public.generation_batches where user_id=pg_temp.aid('owner')),0::bigint,'catalog never invokes model queue');
select is((select count(*) from private.quota_ledger where user_id=pg_temp.aid('owner')),0::bigint,'catalog never reserves image quota');
select is((select count(*) from private.credit_operations where user_id=pg_temp.aid('owner')),0::bigint,'catalog never freezes credits');
select pg_temp.keep('saved',pg_temp.call('save',jsonb_build_object('requestId',pg_temp.aid('save'),'expectedRevision',1,'plan',pg_temp.plan())));
select is((pg_temp.state('saved')->>'revision')::int,2,'editing saves whole-set revision');
select is((select count(*) from public.commerce_revisions where task_id=(pg_temp.state('task')->>'id')::uuid),2::bigint,'prior structured revision remains');
select pg_temp.keep('export',jsonb_build_object('requestId',pg_temp.aid('export'),'revision',2,'runId',pg_temp.state('claim')->'runId'));
select is(jsonb_array_length(pg_temp.call('export',pg_temp.state('export'))->'items'),11,'old whole-set version remains downloadable');
select pg_temp.keep('assetId',pg_temp.state('complete')#>'{runs,0,assets,0,id}');
select ok(pg_temp.call('asset',jsonb_build_object('assetId',pg_temp.state('assetId')))?'path','owned private asset authorizes access');
update public.apparel_assets set expires_at=now()-interval '1 day' where id=(pg_temp.state('assetId')#>>'{}')::uuid;
select throws_ok($$select pg_temp.call('asset',jsonb_build_object('assetId',pg_temp.state('assetId')))$$,'P0001','asset_expired','expired private asset denied');
select throws_ok($$select pg_temp.call('export',pg_temp.state('export'))$$,'P0001','asset_expired','export replay cannot resurrect expired JPEG');
select pg_temp.keep('cleanup',public.claim_cleanup_work());
select is(pg_temp.state('cleanup')->>'jobType','apparel_expiry','expiry uses shared cleanup worker');
select is(jsonb_array_length(pg_temp.state('cleanup')->'objects'),1,'cleanup claims registered private object');
select is(public.cleanup_worker_step((pg_temp.state('cleanup')->>'jobId')::uuid,'apparel_expiry',(pg_temp.state('cleanup')->>'claimToken')::uuid,'complete')->>'accepted','true','fenced cleanup retires asset');
update public.sessions set status='deleting',deleted_at=now() where id=pg_temp.aid('session');
insert into private.cleanup_jobs(job_type,target_id) values('session_delete',pg_temp.aid('session'));
select pg_temp.keep('session-cleanup',public.claim_cleanup_work());
select ok(jsonb_array_length(pg_temp.state('session-cleanup')->'objects')>=19,'session cleanup includes complete set, interrupted intent and seven originals');
select public.cleanup_worker_step((pg_temp.state('session-cleanup')->>'jobId')::uuid,'session_delete',(pg_temp.state('session-cleanup')->>'claimToken')::uuid,'complete');
select is((select count(*) from public.apparel_assets),0::bigint,'session deletion cascades catalog records');
-- A Storage upload that started before deletion can finish after the cascade.
insert into storage.objects(bucket_id,name) values('generated',pg_temp.state('intent')->>'path');
select pg_temp.keep('late-cleanup',public.claim_cleanup_work());
select is(pg_temp.state('late-cleanup')->>'jobType','orphan_apparel','late object survives cascade only until retained-intent cleanup');
select is(pg_temp.state('late-cleanup')#>>'{objects,0,path}',pg_temp.state('intent')->>'path','late object path remains discoverable');
delete from storage.objects where name=pg_temp.state('intent')->>'path';
select is(public.cleanup_worker_step((pg_temp.state('late-cleanup')->>'jobId')::uuid,'orphan_apparel',(pg_temp.state('late-cleanup')->>'claimToken')::uuid,'complete')->>'accepted','true','late cleanup uses fenced lease');
insert into storage.objects(bucket_id,name) values('generated',pg_temp.state('intent')->>'path');
update private.apparel_storage_intents set cleanup_next_at=clock_timestamp()-interval '1 second';
select is(public.claim_cleanup_work()->>'jobType','orphan_apparel','subsequent late writes are swept again');
delete from storage.objects where name=pg_temp.state('intent')->>'path';
-- Account deletion also cascades task rows while retaining late-write paths.
insert into public.sessions(id,user_id,title) values(pg_temp.aid('account-session'),pg_temp.aid('other'),'Account deletion');
select pg_temp.keep('account-task',public.apparel_dispatch(pg_temp.aid('other'),'create',null,jsonb_build_object('requestId',pg_temp.aid('account-create'),'sessionId',pg_temp.aid('account-session'),'plan',pg_temp.plan()),'account-create',gen_random_uuid()));
insert into public.apparel_runs(id,task_id,revision,user_id,request_id,request_hash,status,lease_until) values(pg_temp.aid('account-run'),(pg_temp.state('account-task')->>'id')::uuid,1,pg_temp.aid('other'),pg_temp.aid('account-request'),'account','processing',clock_timestamp()+interval '120 seconds');
insert into public.apparel_assets(id,run_id,claim_token,name,width,height,storage_path) select pg_temp.aid('account-asset'),id,claim_token,'主图/1.jpg',750,1000,'account/late.jpg' from public.apparel_runs where id=pg_temp.aid('account-run');
delete from auth.users where id=pg_temp.aid('other');
insert into storage.objects(bucket_id,name) values('generated','account/late.jpg');
select pg_temp.keep('account-late',public.claim_cleanup_work());
select is(pg_temp.state('account-late')->>'jobType','orphan_apparel','deleted account late upload is discoverable');
select is(pg_temp.state('account-late')#>>'{objects,0,path}','account/late.jpg','account cascade preserves intended Storage path');
select is(public.cleanup_worker_step((pg_temp.state('account-late')->>'jobId')::uuid,'orphan_apparel',gen_random_uuid(),'renew')->>'accepted','false','orphan cleanup rejects stale token');
delete from storage.objects where name='account/late.jpg';
select is(public.cleanup_worker_step((pg_temp.state('account-late')->>'jobId')::uuid,'orphan_apparel',(pg_temp.state('account-late')->>'claimToken')::uuid,'complete')->>'accepted','true','account late write finishes fenced cleanup');
select ok(exists(select 1 from private.credit_price_versions where version='2026-09-15.1' and prices@>'[{"model":"seedream-4.5","unitMinor":30}]'),'historical Seedream catalog remains immutable');
select is((select jsonb_array_length(prices) from private.credit_price_versions where version='2026-10-06.1'),8,'new catalog has eight prices');
select * from finish();
rollback;
